package com.bank.portal.web; import com.bank.portal.service.CardApplicationService; import com.bank.portal.web.ApiDtos.*; import jakarta.validation.Valid; import java.util.*; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/card-requests") @RequiredArgsConstructor public class CardApplicationController {private final CardApplicationService service;@PostMapping @PreAuthorize("hasRole('CUSTOMER')") public CardApplicationView submit(@Valid @RequestBody CardApplicationInput r,Authentication a){return service.submit(a.getName(),r);}@GetMapping("/mine") @PreAuthorize("hasRole('CUSTOMER')") public List<CardApplicationView> mine(Authentication a){return service.mine(a.getName());}@GetMapping @PreAuthorize("hasRole('STAFF')") public List<CardApplicationView> pending(){return service.pending();}@PatchMapping("/{id}") @PreAuthorize("hasRole('STAFF')") public CardApplicationView review(@PathVariable Long id,@Valid @RequestBody CardApplicationReview r,Authentication a){return service.review(id,r,a.getName());}}
